/* ============================================================
   WORD_5000.js — словарь режима «СЛОВА» (5000 слов)
   Глобальная переменная: COURSE
   ЕДИНАЯ СТРУКТУРА записи (v70): [англ, рус, транскрипция, уровень, id, score,
                   new_level, old_level, score_difficulty, level_difficulty, sense_no]
     [0] англ          — английское слово
     [1] рус           — перевод
     [2] транскрипция  — IPA
     [3] уровень       — РАБОЧИЙ номер раздела сложности (0..8);
                         с v67 равен level_difficulty [9] (разбивка
                         по сложности для русскоговорящего). Преды-
                         дущие разбивки сохранены: частотная — в
                         new_level [6], исходная позиционная — в
                         old_level [7]
     [4] id            — ПОСТОЯННЫЙ числовой ID слова (см. правила ниже)
     [5] score         — СЛУЖЕБНАЯ оценка сложности слова 1..99
                         (приложением игнорируется, см. ниже)
     [6] new_level     — СЛУЖЕБНЫЙ уровень 0..8, выведенный ТОЛЬКО
                         из score (приложением игнорируется, см. ниже)
     [7] old_level     — СЛУЖЕБНАЯ копия исходного уровня [3]
                         (архив старой разбивки; приложением игнорируется)
     [8] score_difficulty — СЛУЖЕБНАЯ сложность 1..99 ДЛЯ РУССКО-
                         ГОВОРЯЩЕГО (модель ниже; игнорируется)
     [10] sense_no    — СЛУЖЕБНЫЙ номер значения (см. ниже);
                         приложением игнорируется
     [9] level_difficulty — СЛУЖЕБНЫЙ уровень 0..8, выведенный
                         ТОЛЬКО из score_difficulty [8] по той же
                         сетке шага 11, что и new_level: 1–11→0(A),
                         12–22→1, … 89–99→8(C++). Черновик разбивки
                         наборов под русскоговорящих; приложение
                         поле НЕ читает. Чтобы сделать эту разбивку
                         рабочей — скопировать [9] → [3].

   9 разделов сложности → значение поля [3]:
     0=A  1=A+  2=A++  3=B  4=B+  5=B++  6=C  7=C+  8=C++
   A/A+/A++ — самые необходимые слова, C/C+/C++ — самые редкие.

   ═══ ПРАВИЛА РАБОТЫ С ID (важно!) ═══════════════════════════
   Весь прогресс игроков (веса, «просмотрено», статистика по
   словам, правки перевода) и облачная база (user_progress.item_id
   для mode_name = 'words') привязаны к ID, а НЕ к позиции слова
   в этом файле. Поэтому:
   • ID слова НИКОГДА не меняется и НИКОГДА не переиспользуется.
     Даже если слово удалено — его ID остаётся «занятым» навсегда.
   • Чтобы ПЕРЕНЕСТИ слово в другой набор (A→B→C и т.д.) —
     измени ТОЛЬКО поле [3] (0..8). Вес и вся статистика слова
     сохранятся автоматически, ничего больше делать не нужно.
   • Новое слово получает ID = (максимальный существующий ID + 1).
     Сейчас заняты ID 0..4999, значит следующее новое слово = 5000.
   • Порядок строк в файле влияет только на порядок выдачи
     «новых» слов в игре (от простого к сложному) и на разбивку
     «соток» в режиме General — прогресс от порядка не зависит.
   • При миграции v60 ID присвоены равными старым индексам
     (0..4999), поэтому весь накопленный прогресс (локальный и
     облачный) корректен без какого-либо преобразования данных.

   ═══ ПОЛЕ [5] score — служебная сложность (v61) ═════════════
   Беспристрастная оценка «насколько слово сложное/редкое»:
   1 = максимально простое и частое (I, you, and),
   99 = самое редкое в списке. Считалась НЕЗАВИСИМО от поля
   уровня [3]: все 5000 слов отранжированы между собой по
   корпусной частотности английского (Zipf-частоты, проект
   wordfreq: Wikipedia/субтитры/книги/новости/соцсети), ранг
   растянут на шкалу 1..99; одинаковая частота = одинаковый
   балл. Приложение это поле НЕ читает — оно только для
   ручной работы со словарём (например, пересборки наборов).

   ═══ ПОЛЕ [6] new_level — служебный уровень по score (v62) ══
   Выведен МЕХАНИЧЕСКИ только из поля score [5] по сетке:
     score  1–11 → 0 (A)      34–44 → 3 (B)      67–77 → 6 (C)
           12–22 → 1 (A+)     45–55 → 4 (B+)     78–88 → 7 (C+)
           23–33 → 2 (A++)    56–66 → 5 (B++)    89–99 → 8 (C++)
   Поле уровня [3] при этом НЕ менялось. Приложение читает только
   [3]; new_level — черновик для ручной пересборки наборов: чтобы
   реально перенести слово, скопируй значение из [6] в [3].

   ═══ ПОЛЕ [7] old_level — архив исходного уровня (v63) ══════
   Точная копия поля [3] на момент v63 — до какой-либо
   пересборки наборов. Если [3] будет массово заменён на
   new_level, здесь навсегда останется исходная (позиционная)
   разбивка 500·500·500·550·550·550·600·600·650, и её можно
   будет восстановить обратной копией [7] → [3]. Приложение
   это поле НЕ читает.

   ═══ ПОЛЕ [8] score_difficulty — модель сложности (v65) ═════
   Сложность слова 1..99 именно для русскоговорящего ученика.
   База — корпусная частотность (поле score [5]), к ней пять
   объяснимых поправок:
   1. УЗНАВАЕМОСТЬ ФОРМЫ (когнаты). Английское слово трансли-
      терируется в кириллицу, перевод — в латиницу; считается
      сходство (Левенштейн, с учётом пар з/с, е/э, и/ы). Если
      форма совпадает с переводом или известным русским заим-
      ствованием (такси, зебра, паспорт, томат) — score ×0.35
      (сильный когнат) или ×0.65 (частичный): слово фактически
      уже знакомо, остаётся только узнать его в латинице.
   2. ТЕМАТИЧЕСКАЯ БАЗА (×0.45). Дни недели, месяцы, числи-
      тельные, семья, тело, еда/посуда, дом, школа, одежда,
      базовые животные, цвета, погода, приветствия — конкрет-
      ная бытовая лексика первых месяцев обучения: в корпусах
      она редка, но осваивается рано и легко (образ + пара).
      Скидки 1 и 2 не суммируются — применяется бОльшая.
   3. ДЛИНА СЛОВА: ≤3 букв −3; 7–8 +3; 9–10 +6; ≥11 +9 —
      нагрузка на запоминание растёт с длиной.
   4. ОРФОГРАФИЧЕСКАЯ НЕПРОЗРАЧНОСТЬ: ough/augh +5, немые
      kn-/wr-/ps-/gn-/-mb +4, межзубный th +2 (капом 8) —
      слова, где написание расходится с чтением.
   6. ФРАЗОВЫЕ ГЛАГОЛЫ (v68). Сочетания «глагол + частица»
      (get up, take in, put off…) идиоматичны: значение НЕ
      выводится из компонентов, хотя компоненты сверхчастотны
      и корпусный score обманчиво мал. Поэтому для них
      sd := max(sd, 34 + score×40/98), т.е. минимум набор B,
      а редкие тянутся к C (потолок поправки 77). Связки
      due to / according to фразовыми не считаются.
   5. ГРАММАТИЧНОСТЬ И ЛОЖНЫЕ ДРУЗЬЯ. Служебно-дискурсивные
      слова (though, whether, however, shall…) — минимум 32+6:
      они частые, но требуют грамматики, а не пары «слово-
      перевод». Ложные друзья (magazine, list, data, brilliant,
      artist…) +12 и минимум 40 — похожесть формы обманывает.
   7. РАСТЯЖКА ХВОСТА (v69). Сырые значения ≥89 монотонно
      отображаются в 89..99 (по максимуму выборки), чтобы
      редкие длинные слова не сбивались кучей на отметке 99.
      Порог 89 — нижняя граница C++, уровни от растяжки не
      меняются, порядок слов сохраняется.
   Итог округляется и зажимается в 1..99. Приложение поле НЕ
   читает — это материал для ручной пересборки наборов под
   русскоговорящую аудиторию.

   ═══ ПОЛЕ [10] sense_no — номер значения слова (v70) ════════
   Какому по счёту значению английского слова соответствует
   взятый перевод: 1 = основное (первое) значение, 2 = второе,
   3 = третье. Проставлено ручной вычиткой всех 5000 пар по
   лексикографическому принципу доминирования значений (как
   упорядочивают словари и переводчики; точный порядок Google
   Переводчика недоступен и может отличаться на ±1 у смежных
   значений). Примеры: train=поезд → 1, train=тренироваться →
   2; iron=железо → 1, iron=гладить → 3; present=подарок → 1,
   present=присутствующий → 2, present=настоящее → 3.
   Слов с sense_no > 1 — около 110, у остальных перевод
   соответствует первому значению. Приложение поле НЕ читает.
   ============================================================ */
